// src/server.js
import { config } from './config.js';          // throws if required env vars are missing
import app from './app.js';

if (config.isProd && config.jwtSecret.length < 32) {
  throw new Error('JWT_SECRET must be at least 32 characters in production');
}

const server = app.listen(config.port, '0.0.0.0', () => {
  console.log(JSON.stringify({ msg: 'listening', port: config.port, env: config.env, node: process.version }));
});

server.keepAliveTimeout = 65_000;   // longer than most load balancers' idle timeout (60s)
server.headersTimeout = 66_000;
server.requestTimeout = 30_000;

process.on('unhandledRejection', (err) => { console.error(err); process.exit(1); });
process.on('uncaughtException', (err) => { console.error(err); process.exit(1); });

# /etc/nginx/sites-available/myapp
upstream node_app {
    server 127.0.0.1:3000;
    keepalive 32;
}

server {
    listen 80;
    server_name example.com www.example.com;
    return 301 https://example.com$request_uri;
}

server {
    listen 443 ssl http2;
    server_name example.com;

    ssl_certificate     /etc/letsencrypt/live/example.com/fullchain.pem;
    ssl_certificate_key /etc/letsencrypt/live/example.com/privkey.pem;

    client_max_body_size 10m;
    gzip on;
    gzip_types text/css application/javascript application/json image/svg+xml;

    location /assets/ {                     # static files straight from disk
        alias /var/www/myapp/public/assets/;
        expires 1y;
        add_header Cache-Control "public, immutable";
    }

    location / {
        proxy_pass http://node_app;
        proxy_http_version 1.1;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
        proxy_set_header Upgrade $http_upgrade;       # WebSockets
        proxy_set_header Connection "upgrade";
    }
}

